"""Build only the owned offline P1 interface artifacts; no application build."""
from pathlib import Path
ROOT = Path(__file__).resolve().parent / 'prototype'

def doc(page, title, body):
    demo = '<div id="demo" class="demo"></div>' if page != 'index' else '<div class="demo"><p>Three offline interface proposals · synthetic text · 12 October 2026</p></div>'
    return f'''<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><title>{title} · Alongside</title><link rel="stylesheet" href="style.css"></head><body data-page="{page}"><div class="wrap">{demo}<main id="main">{body}</main><footer class="sources"><h2>Sources & design provenance</h2><p>Source metadata: the bounded Ephesians selection and connection reports, 12 October 2026. All prose demonstrations are synthetic; no Scripture, author quotation or editorial answer is reproduced.</p><a href="https://github.com/textcreationpartnership/A41197">TCP A41197 provenance ↗</a><a href="https://github.com/textcreationpartnership/A17705">TCP A17705 provenance ↗</a><p>External links trace originals only. The demonstrations work offline; opening a provenance link requires a connection.</p><p><a href="index.html">Return to the design gallery</a></p></footer></div><noscript><p class="noscript">This design uses local JavaScript for interactive fixtures. Enable JavaScript to explore states; no network service is required.</p></noscript><script src="app.js"></script></body></html>'''

gallery='''<header class="hero"><p class="eyebrow">P1 / Connected library interface study</p><h1>Alongside.<br><em>Read with the library.</em></h1><p>Three connected experiences for moving from a passage or a question to the works we hold. Choose an interface, then explore how it handles available text, unresolved evidence and missing information.</p></header><div class="gallery">
<article><span class="eyebrow">01 / Scripture first</span><div class="mini" aria-hidden="true"><i></i><i></i></div><h2 class="gallery-title">The passage companion</h2><p>Keep the chapter in view. Explore a source beside it, with its basis and availability always visible.</p><a href="passage.html">Explore the passage design →</a></article>
<article><span class="eyebrow">02 / A focused question</span><div class="mini" aria-hidden="true"><i style="flex:.35"></i><i style="flex:1"></i></div><h2 class="gallery-title">The question workspace</h2><p>Separate the question, the evidence and the unresolved disagreements before presenting an answer.</p><a href="topic.html">Explore the topic design →</a></article>
<article><span class="eyebrow">03 / The works we hold</span><div class="mini" aria-hidden="true"><i></i><i></i><i></i></div><h2 class="gallery-title">The acquired shelf</h2><p>Open a contributor, choose a work and inspect the exact edition. A biography is never a prerequisite.</p><a href="shelf.html">Explore the shelf design →</a></article></div>
<div class="gallery-footer"><div><h3>Existing visual language</h3><p>Archivo and Literata, parchment and dark themes, generous type and quiet dividing rules.</p></div><div><h3>Honest availability</h3><p>Seven inspectable states. On-site reading is distinct from connection review and editorial approval.</p></div><div><h3>Contained preparation</h3><p>Offline fixtures only. No published routes, source edits, corpus reads or embedding operations.</p></div></div>'''
passage='''<p class="crumb"><a href="index.html">Design gallery</a> / Passage companion</p><header class="hero"><p class="eyebrow">Scripture & theology / Books & passages</p><h1>A chapter.<br><em>A wider conversation.</em></h1><p>Keep Scripture at the centre. Open a held treatment alongside the chapter, with clear boundaries around what has been located and reviewed.</p></header><div class="reading"><section aria-labelledby="reading-heading"><div class="chapter-bar"><h2 id="reading-heading">Ephesians 1</h2><span class="caption">KJV reading context</span></div><div class="toolbar" aria-label="Chapter navigation"><button id="previous" disabled>← Previous</button><span class="caption">Chapter <span id="chapter-number">1</span> of 6</span><button id="next">Next →</button></div><p class="fixture">Layout placeholders below — not Bible quotations</p><div class="chapter"><div class="verse"><small>01</small><p>[Chapter opening text appears here in the production reader. This fixture preserves the reading measure without reproducing a passage.]</p></div><div class="verse selected"><small>02</small><p>[The selected reading context remains visible while a companion source is inspected.]</p></div><div class="verse"><small>03</small><p>[Continue reading. The companion should support the chapter, without replacing it or presenting a source's interpretation as Scripture.]</p></div></div><button id="bible-route">Open Bible reader →</button></section><aside aria-label="Held source companion"><p class="eyebrow">Alongside this chapter</p><h2>From the held library</h2><label class="edition-select">Choose a treatment<select id="work-choice"><option value="fergusson">Fergusson · Exposition</option><option value="sermons">Calvin · Sermons</option><option value="commentary">Calvin · Commentary</option><option value="hodge">Hodge · Commentary</option></select></label><div id="state-content" aria-live="polite"></div><details><summary>Editorial interpretation</summary><p>No interpretation is supplied in this prototype. A future reviewed explanation would appear separately from Scripture and source quotations.</p></details></aside></div>'''
topic='''<p class="crumb"><a href="index.html">Design gallery</a> / Topic and question</p><header class="hero"><p class="eyebrow">Scripture & theology / Question workspace</p><h1>Ask a narrower<br><em>question.</em></h1><p>A proposed question workspace. Choose what you want to investigate, inspect the evidence, and see what still requires review.</p></header><div class="topic-layout"><nav class="topic-nav" aria-label="Within this question"><a href="#question">The question</a><a href="#evidence">Source evidence</a><a href="#differences">Differences & limits</a><a href="shelf.html">Held author shelves →</a></nav><div><section id="question"><p class="eyebrow">Illustrative topic / Assurance</p><h2 id="question-heading">How should this question be framed?</h2><div class="toolbar" aria-label="Choose a demonstration question"><button data-question="How should this question be framed?" aria-pressed="true">Define the question</button><button data-question="How does the writer distinguish related terms?" aria-pressed="false">Distinguish terms</button></div><div class="callout"><p><b>Answer not prepared.</b> These are synthetic question fixtures. No theological conclusion or source relevance judgment is implied.</p></div></section><section id="evidence"><div class="section-bar"><h2>Inspect the evidence</h2><span class="caption">One illustrative record</span></div><div id="state-content" aria-live="polite"></div></section><section id="differences"><h2>Keep differences visible</h2><div class="question-grid"><div><p class="eyebrow">Author position</p><h3>Who is speaking?</h3><p>A writer may state a position, report an opponent, or answer an objection. The source context must establish which.</p></div><div><p class="eyebrow">Editorial synthesis</p><h3>What can we conclude?</h3><p>No comparison is written here. Future differences must be attributed and supported by distinct, reviewed treatments.</p></div></div><details><summary>What would make this ready?</summary><p>Located evidence, verified attribution, independent-work coverage, public-use decisions and editorial review. Final intake and retrieval gates still apply to comprehensive mining.</p></details></section></div></div>'''
shelf='''<p class="crumb"><a href="index.html">Design gallery</a> / Teachers / Acquired library</p><header class="hero"><p class="eyebrow">Teachers / Acquired library section study</p><h1>The works we hold,<br><em>by contributor.</em></h1><p>Choose an author, then a work and its held edition. A catalogue record and a readable text have different actions.</p></header><p class="shelf-context">Section placement: retain this shelf in the existing acquired-library position below the preceding Teachers sections. This is a section detail, not a replacement page or an additional announcement banner.</p><div class="section-bar"><h2>Acquired authors & texts</h2><span class="caption">3 fixture contributors · 4 work records</span></div><div class="shelves"><section aria-label="Contributors"><label for="search" class="caption">Find a contributor</label><input id="search" class="shelf-search" type="search" placeholder="Name or role" autocomplete="off"><p id="search-count" class="caption" role="status">3 of 3 fixture contributors</p><ul class="contributors"><li><button data-author="fergusson" aria-pressed="false"><strong>James Fergusson</strong><span>Author · 1 selected work</span></button></li><li><button data-author="calvin" aria-pressed="false"><strong>John Calvin</strong><span>Author · 2 selected works</span></button></li><li><button data-author="hodge" aria-pressed="false"><strong>Charles Hodge</strong><span>Author · 1 selected work</span></button></li></ul><div id="search-empty" hidden><p>No contributor matches this fixture search.</p><button id="clear-search">Clear search</button></div></section><section aria-label="Selected contributor shelf"><div id="shelf-placeholder" class="shelf-placeholder"><p class="eyebrow">No contributor selected</p><h3>Open a shelf to begin.</h3><p>Contributor details stay closed until selected. Existing biography and relationship views remain in their original sections.</p><p class="caption">No graph or shared panel sizing is changed by this proposal.</p></div><div id="shelf-panel" hidden><div class="section-bar"><h2 id="shelf-heading"></h2><button id="close-shelf">Close shelf</button></div><label class="edition-select">Work & held edition<select id="edition"></select></label><div id="state-content" aria-live="polite"></div><details><summary>About the contributor</summary><p>Biographical assertions are outside these design fixtures. Author, translator and editor credits remain separate; holding a work does not imply that a biography is recorded.</p></details></div></section></div>'''

for name,title,body in [('index','Alongside — interface gallery',gallery),('passage','Passage companion',passage),('topic','Topic and question',topic),('shelf','Acquired contributor shelf',shelf)]:
    (ROOT/f'{name}.html').write_text(doc(name,title,body),encoding='utf-8')
print('Built gallery and three offline prototypes in the P1 folder.')
